    [8250] = {n="Магическое искусство", d="Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему."},
    [8251] = {n="Волшебная пыль", d="Принесите 10 горстей сияющей пыли верховному магу Ксилему.", tgo={{"Эльф крови-геодезист", "Эльф крови-землемер", "Эльф крови-защитник", "Эльф крови - чародей", "Эвин Шмидт", "Люмина Песнь Ветра"}}},
    [8252] = {n="Кораллы сирен", d="Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.", tgo={{"Сирена из клана Бича Злобы"}}},
    [8253] = {n="Уничтожить Морфаза", d="Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", tgo={{"Морфаз"}}, star={"Огненный рубин", {"MAGE"}}},
    [8254] = {n="Помощь Кенарию", d="Отыщи Огтинка в Азшаре."},
    [8255] = {n="Охота на беговых оленей", d="Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Мохоногий олень"}}},
    [8256] = {n="Лимфа нежити", d="Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tgo={{"Зомби Занзила", "Охотник Занзила", "Скелет-живодер", "Скелет-колдун", "Скелет-ужасень", "Скелет-палач", "Скелет-вождь", "Скелет-послушник"}}},
    [8257] = {n="Кровь Морфаза", d="Убейте Морфаза в затонувшем храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на болоте Печали.", tgo={{"Морфаз"}}, star={"Благословенные четки", {"PRIEST"}}},
    [8276] = {n="Отвоевание Силитуса", d="Поговорите с призывательницей ветров Гордый Рог в крепости Кенария."},
    [8277] = {n="Смертельный яд", d="Принесите Битиссе Шаткобрус из крепости Кенария 8 жал камнехвостых скорпидов и 8 жвал песчаных пауков-быстроногов.", tgo={{"Камнехвостый скорпид"}, {"Песчаный паук-быстроног"}}},
    [8278] = {n="Последняя надежда Ноггла", d="Принесите Битиссе Шаткобрус из крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.", tgo={{"Камнехвостый живодер"}, {"Камнехвостый клешневик"}, {"Скальный паук-скакун"}}},
    [8280] = {n="Надежные поставки", d="Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.", tgo={{"Землечерп"}}},
    [8281] = {n="Обеспечение безопасности", d="Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордый Рог.", tgo={{"Земляной сокрушитель"}}},
    [8284] = {n="Сумеречная тайна", d="Геолог Ехидная из крепости Кенария просит вас собрать 8 фрагментов сумеречной таблички.", objs={"Фрагмент Сумеречной таблички"}},
    [8285] = {n="Дезертир", d="Отнесите восстановленную табличку отшельнику Ортеллу в Силитус."},
    [8304] = {n="Дражайшая Наталиа", d="Допросите обитателей лагеря Бронзоборода по поручению командира Мар'алита из крепости Кенария. Этот лагерь находится южнее крепости Кенария.\nСобрав необходимые сведения, вернитесь к командиру Мар'алиту.", tgo={{"Франкал Каменный Мост"}, {"Рутгар Знакописец"}}},
